func testGlobal() []globalview.Region {
	var out []globalview.Region
	for _, summary := range testRegions() {
		out = append(out, globalview.Region{Cell: summary.Region, Rollup: &globalview.Rollup{Cell: summary.Region}})
	}
	return out
}

func fullJournal() (*Journal, *fakeInsights, *fakeDecisions) {
	history := observability.NewHistory(observability.HistoryConfig{})
	for minute := 120; minute >= 0; minute-- {
		at := time.Now().Add(-time.Duration(minute) * time.Minute)
		history.Append(at, []observability.Sample{
			{Metric: observability.HistCPUUtilization, Labels: observability.L("member", "ctl-1"), Value: 0.4},
			{Metric: observability.HistMembersAnswering, Value: 2},
			{Metric: observability.HistFSRatio, Labels: observability.L("member", "ctl-1", "role", "nats"),
				Value: 0.7 + float64(120-minute)*0.001},
			{Metric: observability.HistOCICalls, Labels: observability.L("operation", "compute GET /instances"),
				Value: float64(120-minute) * 60, Counter: true},
		})
	}
	source := &fakeInsights{evaluation: insights.Evaluation{At: testNow,
		Insights: []insights.Insight{testInsight("disk:ctl-1", "ctl-1 nats filesystem full in about 2d", insights.SeverityWarning, "fra")},
		Counts:   insights.Counts{Warning: 1}}}
	decisions := &fakeDecisions{decisions: testDecisions()}
	journal := &Journal{Decisions: decisions, History: history, Insights: source, Summaries: fakeSummaries{},
		Local:  func(context.Context) regionview.Summary { return testRegions()[0] },
		Global: testGlobalView(),
		Versions: fakeVersions{{Region: "fra", Kind: "controller", Unit: "ctl-1", Version: "v0.43.0"},
			{Region: "fra", Kind: "controller", Unit: "ctl-2", Version: "v0.42.1"},
			{Region: "sfo", Kind: "seat", Unit: "orders-1", Version: "terrabase 3.8.1"}},
		Rollouts: fakeRollouts{{ID: "0000000000N6KCZG3MWDGZ0WBE", Release: "v0.43.0", Phase: "batch-1", PhaseStarted: testNow.Add(-time.Hour),
			PhaseDeadline: testNow.Add(-time.Minute)}},
		Volumes: fakeVolumes{{ID: "vol-stuck", Host: "host-a", State: "attaching", StateSince: testNow.Add(-time.Hour)}},
		Qualification: fakeQualification{{Release: "v0.43.1-rc.1", Status: "running", Time: testNow,
			Suites: []QualificationStep{{Name: "rolling upgrade", Status: "running"}}}},
		Inventory: fakeInventory{{Kind: "instance", ID: "ocid1.instance.x", Name: "host-old", State: "STOPPED", Drift: "unmanaged"}}}
	return journal, source, decisions
}

func journalDashboard(options Options) (*Dashboard, *fakeInsights, *fakeDecisions) {
	journal, source, decisions := fullJournal()
	options.Journal = journal
	options.Snapshots = fixedSnapshots{snapshot: memberSnapshot()}
	options.Health = readyHealth(true)
	return newTestDashboard(options), source, decisions
}

func overviewRollup(cell string, observed time.Time, peers []string) globalview.Rollup {
	rollup := globalview.Rollup{Version: globalview.Version, Cell: cell, ObservedAt: observed,
		Health:      globalview.Health{Status: globalview.Healthy},
		Controllers: globalview.Controllers{Expected: 3, Ready: 3, Leader: cell + "-ctl-1"},
		Totals: globalview.Totals{Nodes: 12, Ready: 12, CPUCores: 96, CPUUsedCores: 24,
			MemoryBytes: 384 << 30, MemoryUsedBytes: 192 << 30, DiskBytes: 6000 << 30, DiskUsedBytes: 1200 << 30,
			NetworkRxBps: 12000, NetworkTxBps: 6000, Load1: 6},
		Replication: globalview.Replication{LagSeconds: floatPtr(1.5)},
		Cost:        &globalview.Cost{Currency: "USD", PerHour: 12.5, MonthForecast: 9000, ObservedAt: observed},
		Autoscale: globalview.Autoscale{Services: []globalview.Scaling{
			{Service: "api", Replicas: 3, Goal: 3}, {Service: "worker", Replicas: 2, Goal: 4},
			{Service: "db", Replicas: 1, Goal: 1}, {Service: "cache", Replicas: 2, Goal: 2}}},
	}
	for index := range 12 {
		rollup.Nodes = append(rollup.Nodes, globalview.Node{Name: fmt.Sprintf("%s-n%02d", cell, index),
			Health: globalview.NodeOK, ReportedAt: observed, CPU: floatPtr(0.25), CPUCores: 8,
			MemoryBytes: 32 << 30, MemoryUsedBytes: 16 << 30, DiskBytes: 500 << 30, DiskUsedBytes: 100 << 30,
			NetworkRxBps: floatPtr(1000), NetworkTxBps: floatPtr(500), Load1: floatPtr(0.5),
			Services: []globalview.Service{{Role: "controller", State: "ready", Digest: "sha256:abc"},
				{Role: "terrabase", State: "serving"}, {Role: "nats", State: "ready"}},
			Filesystems: []globalview.Filesystem{{Role: "root", SizeBytes: 100 << 30, UsedBytes: 40 << 30},
				{Role: "state", SizeBytes: 400 << 30, UsedBytes: 60 << 30}}})
	}
	for index := range 4 {
		rollup.Volumes = append(rollup.Volumes, globalview.Volume{ID: fmt.Sprintf("%s-vol-%d", cell, index),
			Node: fmt.Sprintf("%s-n%02d", cell, index), State: "attached"})
	}
	for _, peer := range peers {
		rollup.Links = append(rollup.Links, globalview.Link{Region: peer, Reach: decisionlog.RegionOK,
			RTTMillis: floatPtr(40), LagSeconds: floatPtr(2), ObservedAt: observed})
	}
	for index := range 6 {
		rollup.Routes = append(rollup.Routes, globalview.Route{From: fmt.Sprintf("%s-ctl-%d", cell, index),
			To: cell + "-ctl-1", RTTMillis: floatPtr(0.4)})
	}
	for index := range 10 {
		rollup.Errors = append(rollup.Errors, globalview.Error{At: observed.Add(-time.Duration(index) * time.Minute),
			Level: "ERROR", Component: "orchestrator", Message: "lease renewal slow", Count: index + 1,
			Nodes: []string{cell + "-n01", cell + "-n02", cell + "-n03"}})
	}
	for index := range 10 {
		rollup.Databases = append(rollup.Databases, globalview.Database{ID: fmt.Sprintf("%s-db-%d", cell, index),
			Project: cell + "-project", ReplicationBytesPerSecond: float64(1000 * (index + 1)), LagSeconds: 1})
	}
	return rollup
}

func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

// Regions lists local first, then every other listed region by cell.
func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

// Region returns one listed region; false when cell is not listed.
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

// Changed returns a channel closed on the next accepted rollup.
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

// Accept keeps r when it is newer than the held rollup of its cell.
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true
}

func (v *View) listed() []string {
	var others []string
	if v.regions != nil {
		for _, raw := range v.regions() {
			cell := normalize(raw)
			if cell == "" || cell == v.local || slices.Contains(others, cell) {
				continue
			}
			others = append(others, cell)
		}
	}
	slices.Sort(others)
	if v.local == "" {
		return others
	}
	return append([]string{v.local}, others...)
}

// region reads one listed cell. Callers hold mu.
func (v *View) region(cell string) Region {
	r := v.rollups[cell]
	return Region{
		Cell:   cell,
		Rollup: r,
		Stale:  r != nil && v.now().Sub(r.ObservedAt) > StaleAfter,
	}
}

func validate(r Rollup, now time.Time) error {
	if r.Version != Version {
		return fmt.Errorf("rollup version %d, want %d", r.Version, Version)
	}
	if token, err := protocol.RegionToken(r.Cell); err != nil || token != r.Cell {
		return fmt.Errorf("rollup cell %q is not a region token", r.Cell)
	}
	if r.ObservedAt.IsZero() || r.ObservedAt.After(now.Add(time.Minute)) {
		return fmt.Errorf("rollup observed_at %s is outside the clock window", r.ObservedAt)
	}
	return nil
}

release.text:
func releasePage(t *testing.T, decisions ...decisionlog.Decision) string {
	t.Helper()
	return fixturePage(t, view{Decisions: &decisionlog.Result{Decisions: decisions}}, "/releases")
}

func pageTarget(t *testing.T, current view) string {
	t.Helper()
	body := fixturePage(t, current, "/releases")
	match := regexp.MustCompile(`(?s)<tbody>\s*<tr>\s*<th scope="row">Controllers</th>\s*<td><code>([^<]*)</code>`).FindStringSubmatch(body)
	if len(match) != 2 {
		t.Fatalf("controller target missing in release matrix")
	}
	return html.UnescapeString(match[1])
}

func releaseID(decision decisionlog.Decision) (id, name string) {
	if decision.Subject.Kind == "release" && decision.Subject.ID != "" {
		return decision.Subject.ID, cmp.Or(decision.Subject.Name, decision.Attrs["version"], decision.Subject.ID)
	}
	if id := decision.Attrs["release"]; id != "" {
		return id, cmp.Or(decision.Attrs["version"], id)
	}
	return "", ""
}

// releaseVersion is the identity a unit running the release reports: its
// version attribute, else a subject name that is a version label, else the
// release ID (a digest). The rollout producer names its subject
// "<kind>/<rollout>", which is a display label, never a unit's version.
func releaseVersion(decision decisionlog.Decision, id string) string {
	if version := decision.Attrs["version"]; version != "" {
		return version
	}
	if name := decision.Subject.Name; decision.Subject.Kind == "release" && name != "" && !strings.Contains(name, "/") {
		return name
	}
	return id
}

// aborted reports a rollout aborted for good (preflight failure, preflight
// timeout or an operator abort), as opposed to a temporary hold.
func aborted(decision decisionlog.Decision) bool {
	return decision.Kind == decisionlog.KindHeld && decision.Attrs["phase"] == "aborted"
}

// releaseStage places a decision on the timeline.
func releaseStage(decision decisionlog.Decision) string {
	if stage := decision.Attrs["stage"]; slices.Contains(releaseStages, stage) {
		return stage
	}
	switch decision.Kind {
	case decisionlog.KindReleaseAdmitted:
		return "signed"
	case decisionlog.KindUpgradeStarted:
		return "staged"
	case decisionlog.KindCanaryPromoted:
		return "canary"
	case decisionlog.KindHeld, decisionlog.KindHoldCleared, decisionlog.KindFrozen:
		if aborted(decision) {
			return "outcome"
		}
		return "soak"
	case decisionlog.KindBatchPromoted:
		return "batches"
	case decisionlog.KindRolloutCompleted, decisionlog.KindRollback:
		return "outcome"
	default:
		return ""
	}
}

func (current view) releases() []releaseView {
	coverage := current.decisionCoverage()
	byID := map[string]*releaseView{}
	lanes := map[string]map[string]map[string]*releaseStep{}
	// Oldest first, so a later decision for the same step wins.
	decisions := slices.Clone(current.decisions())
	slices.Reverse(decisions)
	for index := range decisions {
		decision := &decisions[index]
		id, name := releaseID(*decision)
		stage := releaseStage(*decision)
		if id == "" || stage == "" {
			continue
		}
		release := byID[id]
		if release == nil {
			release = &releaseView{ID: id, Name: name, Version: releaseVersion(*decision, id), First: decision.Time}
			byID[id] = release
			lanes[id] = map[string]map[string]*releaseStep{}
		}
		if version := decision.Attrs["version"]; version != "" {
			release.Version = version
		}
		if (decision.Kind == decisionlog.KindReleaseAdmitted || decision.Kind == decisionlog.KindUpgradeStarted) &&
			(release.Started.IsZero() || decision.Time.Before(release.Started)) {
			release.Started = decision.Time
		}
		release.Last = decision.Time
		if lanes[id][decision.Region] == nil {
			lanes[id][decision.Region] = map[string]*releaseStep{}
		}
		steps := lanes[id][decision.Region]
		step := steps[stage]
		if step == nil {
			step = &releaseStep{Stage: stage}
			steps[stage] = step
		}
		step.Count++
		step.Decision = decision
		step.Status = decisionStatus(decision.Status)
		step.Label = kindLabel(decision.Kind)
		switch decision.Kind {
		case decisionlog.KindReleaseAdmitted:
			step.Label = cmp.Or(decision.Attrs["delegation"], "admitted")
			// Admission checks fencing, known-bad digests and attempts,
			// not CI: the qualified step shows only explicit evidence.
			if qualification := decision.Attrs["qualification"]; qualification != "" {
				steps["qualified"] = &releaseStep{Stage: "qualified", Decision: decision, Count: 1,
					Status: qualificationStatus(qualification), Label: qualification}
			}
		case decisionlog.KindBatchPromoted:
			step.Label = "batch " + cmp.Or(decision.Attrs["batch"], strconv.Itoa(step.Count))
			if total := decision.Attrs["batches"]; total != "" {
				step.Label += " of " + total
			}
		case decisionlog.KindRollback:
			// A rollback is journaled when it starts and again when the
			// previous version is restored; only the latter is done.
			step.Label, step.Status = "rolling back", "serious"
			if decision.Status == decisionlog.StatusRolledBack {
				step.Label = "rolled back"
			}
			release.Reason = cmp.Or(decision.Reason, decision.Summary)
		case decisionlog.KindRolloutCompleted:
			step.Label = "complete"
		case decisionlog.KindHeld, decisionlog.KindFrozen:
			if aborted(*decision) {
				step.Label, step.Status = "aborted", "bad"
				release.Reason = cmp.Or(decision.Reason, decision.Summary)
				break
			}
			step.Label, step.Status = kindLabel(decision.Kind), "warn"
			if release.Reason == "" {
				release.Reason = cmp.Or(decision.Reason, decision.Summary)
			}
		case decisionlog.KindHoldCleared:
			step.Label = "soak passed"
		}
	}
	out := make([]releaseView, 0, len(byID))
	for id, release := range byID {
		complete, rolledBack, rollingBack, abortedLanes, running := 0, 0, 0, 0, 0
		for _, region := range current.orderRegions(slices.Collect(maps.Keys(lanes[id]))) {
			steps := lanes[id][region]
			lane := releaseLane{Region: region}
			for _, stage := range releaseStages {
				if step := steps[stage]; step != nil {
					lane.Steps = append(lane.Steps, *step)
				} else {
					lane.Steps = append(lane.Steps, releaseStep{Stage: stage})
				}
			}
			release.Lanes = append(release.Lanes, lane)
			switch outcome := steps["outcome"]; {
			case outcome != nil && outcome.Decision.Kind == decisionlog.KindRollback &&
				outcome.Decision.Status == decisionlog.StatusRolledBack:
				rolledBack++
			case outcome != nil && outcome.Decision.Kind == decisionlog.KindRollback:
				rollingBack++
			case outcome != nil && aborted(*outcome.Decision):
				abortedLanes++
			case outcome != nil:
				complete++
			default:
				running++
			}
		}
		release.Partial = coverage != coverageComplete
		unseen := 0
		for _, region := range current.Global {
			if lanes[id][region.Cell] == nil {
				unseen++
			}
		}
		// The window is the decision query's (releaseHistory), not the
		// release's whole life: a region without a lane may have finished
		// it earlier.
		switch {
		case rollingBack > 0:
			release.Status, release.Label = "serious", "rolling back in "+itoa(rollingBack)+" region(s)"
		case rolledBack > 0:
			release.Status, release.Label = "serious", "rolled back in "+itoa(rolledBack)+" region(s)"
		case abortedLanes > 0:
			release.Status, release.Label = "bad", "aborted in "+itoa(abortedLanes)+" region(s)"
		case running == 0 && release.Partial:
			// A region that did not answer may still be rolling out (or
			// may have rolled back): completion covers observed regions.
			release.Status, release.Label = "warn", "complete in "+itoa(complete)+" observed region(s); history partial"
		case running == 0 && unseen > 0:
			release.Status, release.Label = "ok", "complete in "+itoa(complete)+" region(s); "+itoa(unseen)+
				" with no activity in the queried window"
		case running == 0:
			release.Status, release.Label = "ok", "complete everywhere"
		default:
			release.Status, release.Label = "run", "in progress: "+itoa(complete)+" of "+itoa(len(release.Lanes))+" regions complete"
			if release.Partial {
				release.Label += "; history partial"
			}
		}
		out = append(out, *release)
	}
	slices.SortFunc(out, func(left, right releaseView) int {
		return cmp.Or(right.Last.Compare(left.Last), cmp.Compare(left.ID, right.ID))
	})
	return out
}

func (current view) targetVersion(kind string) string {
	counts := map[string]int{}
	for _, unit := range current.Versions {
		if unit.Version != "" && unit.Kind == kind {
			counts[unit.Version]++
		}
	}
	bad := map[string]bool{}
	var newest *releaseView
	releases := current.releases()
	for index := range releases {
		if releases[index].Status == "serious" {
			bad[releases[index].Version] = true
		}
	}
	for index := range releases {
		release := &releases[index]
		// Only a release whose start was observed can be ordered by it:
		// the earliest loaded decision of a bounded or partial query is
		// not its start.
		if bad[release.Version] || counts[release.Version] == 0 || release.Started.IsZero() {
			continue
		}
		if newest == nil || release.Started.After(newest.Started) ||
			release.Started.Equal(newest.Started) && release.Version > newest.Version {
			newest = release
		}
	}
	if newest != nil {
		return newest.Version
	}
	best := ""
	for _, version := range slices.Sorted(maps.Keys(counts)) {
		if bad[version] {
			continue
		}
		if best == "" || counts[version] >= counts[best] {
			best = version
		}
	}
	return best
}

func (current view) matrixRegions() []string {
	seen := map[string]bool{}
	var regions []string
	for _, region := range current.Global {
		seen[region.Cell] = true
		regions = append(regions, region.Cell)
	}
	for _, unit := range current.Versions {
		if !seen[unit.Region] {
			seen[unit.Region] = true
			regions = append(regions, unit.Region)
		}
	}
	return regions
}

func (current view) matrixKinds() []string {
	present := map[string]bool{}
	for _, unit := range current.Versions {
		present[unit.Kind] = true
	}
	var kinds []string
	for _, kind := range unitKinds {
		if present[kind] {
			kinds = append(kinds, kind)
			delete(present, kind)
		}
	}
	return append(kinds, slices.Sorted(maps.Keys(present))...)
}

func (current view) versionCell(region, kind string) versionCell {
	target := current.targetVersion(kind)
	counts := map[string]int{}
	cell := versionCell{}
	for _, unit := range current.Versions {
		if unit.Region == region && unit.Kind == kind {
			counts[unit.Version]++
			cell.Total++
		}
	}
	for _, version := range slices.Sorted(maps.Keys(counts)) {
		cell.Versions = append(cell.Versions, versionCount{Version: version, Count: counts[version], Target: version == target})
		if version != target {
			cell.Drift = true
		}
	}
	cell.Drift = cell.Drift || len(cell.Versions) > 1
	return cell
}

// driftedUnits lists units off the target version.
func (current view) driftedUnits() []UnitVersion {
	targets := map[string]string{}
	var out []UnitVersion
	for _, unit := range current.Versions {
		if _, ok := targets[unit.Kind]; !ok {
			targets[unit.Kind] = current.targetVersion(unit.Kind)
		}
		if unit.Version != targets[unit.Kind] {
			out = append(out, unit)
		}
	}
	slices.SortFunc(out, func(left, right UnitVersion) int {
		return cmp.Or(cmp.Compare(left.Region, right.Region), cmp.Compare(left.Kind, right.Kind),
			cmp.Compare(left.Unit, right.Unit))
	})
	return out
}

func (current view) decisionCoverage() coverage {
	switch {
	case current.Journal == nil || current.Journal.Decisions == nil:
		return coverageMissing
	case current.Decisions == nil:
		return coverageFailed
	case current.Decisions.Partial || current.Decisions.Truncated:
		return coveragePartial
	}
	for _, status := range current.Decisions.Regions {
		if status.State != decisionlog.RegionOK {
			return coveragePartial
		}
	}
	return coverageComplete
}

templ releasesBody(current view) {
	<div id="content">
		<div class="page-head">
			<h1>Releases and upgrades</h1>
			<small class="muted">last 7 days of release decisions · click a step for its decision record</small>
		</div>
		@notes(current)
		if current.Chain != nil {
			@chainPanel(current, *current.Chain)
		}
		<article>
			<div class="chart-title">
				<h2>Version matrix <small>regions × units</small></h2>
				<span class="legend">
					@statusPill("ok", "on target")
					@statusPill("warn", "drift or mixed")
				</span>
			</div>
			@versionMatrix(current)
		</article>
		<h2>Release timelines</h2>
		if current.Journal == nil || current.Journal.Decisions == nil {
			@journalMissing("Release timelines")
		} else if releases := current.releases(); len(releases) == 0 && current.decisionCoverage() != coverageComplete {
			<article>
				@historyUnavailable(current, "Release history")
			</article>
		} else if len(releases) == 0 {
			<article>
				<p class="empty">No release decisions in the last 7 days. The rollout and selfupdate slices record release_admitted, canary, batch and rollback decisions here as they run.</p>
			</article>
		} else {
			if current.decisionCoverage() != coverageComplete {
				@historyUnavailable(current, "Release history")
			}
			for _, release := range releases {
				@releaseCard(current, release)
			}
		}
	</div>
}

templ releaseCard(current view, release releaseView) {
	<article class={ "edge", sClass(release.Status) }>
		<div class="chart-title">
			<h3>
				<code>{ short(release.Name, 40) }</code>
				if release.Name != release.ID {
					<small class="mono">{ short(release.ID, 24) }</small>
				}
			</h3>
			<span>
				@statusPill(release.Status, release.Label)
				<small class="muted">
					{ " started " }
					@ago(release.First)
				</small>
			</span>
		</div>
		if release.Reason != "" {
			<p class={ "note", templ.KV("warn", release.Status != "ok") }>{ release.Reason }</p>
		}
		<div class="table-scroll">
			<div class="steps">
				<span></span>
				for _, stage := range releaseStages {
