func pageCharts(t *testing.T, body string) []chartSpec {
	t.Helper()
	var charts []chartSpec
	for _, match := range regexp.MustCompile(`data-spec="([^"]*)"`).FindAllStringSubmatch(body, -1) {
		var spec chartSpec
		if err := json.Unmarshal([]byte(html.UnescapeString(match[1])), &spec); err != nil {
			t.Fatal(err)
		}
		charts = append(charts, spec)
	}
	return charts
}

func NewHistory(config HistoryConfig) *History {
	if config.Interval <= 0 {
		config.Interval = DefaultHistoryInterval
	}
	if config.MaxSeries <= 0 {
		config.MaxSeries = DefaultHistorySeries
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = HistoryRetention
	}
	return &History{config: config, series: map[string]*series{}, dropMinutes: map[int64]bool{}}

func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

func TierFor(start, now time.Time) string {
	age := now.Sub(start)
	switch {
	case age <= rawRetention:
		return TierRaw
	case age <= oneMinuteRetention:
		return Tier1m
	case age <= fiveMinuteRetention:
		return Tier5m
	default:
		return Tier1h
	}
}

// Range returns matching series' points in [Start, End], oldest first.
func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}

func (current view) storageForecasts() ([]forecast, chartSpec) {
	if current.Journal == nil || current.Journal.History == nil {
		return nil, chartSpec{Kind: "line", Empty: "No storage history yet."}
	}
	window := max(current.State.Range.Duration, 24*time.Hour)
	result := current.Journal.History.Range(observability.HistoryQuery{Metric: observability.HistFSRatio,
		Start: current.Now.Add(-window), End: current.Now})
	var forecasts []forecast
	var series []chartSeries
	for _, found := range result.Series {
		// The trend is fitted on raw samples; rounding is for display only,
		// since it can flatten a slow but real fill near 100%.
		raw := make([][2]float64, 0, len(found.Points))
		points := make([][2]float64, 0, len(found.Points))
		for _, point := range found.Points {
			raw = append(raw, [2]float64{float64(point.Time.UnixMilli()), point.Value})
			points = append(points, [2]float64{float64(point.Time.UnixMilli()), round(point.Value)})
		}
		if len(points) == 0 {
			continue
		}
		name := found.Labels["member"] + " " + found.Labels["role"]
		entry := forecast{Name: name, Used: points[len(points)-1][1], Status: "ok"}
		entry.Full, entry.Known = timeToFull(raw)
		_, _, entry.Trend = linearForecast(raw)
		switch {
		case !entry.Trend:
			entry.Status = "idle"
		case entry.Known && entry.Full < 72*time.Hour:
			entry.Status = "bad"
		case entry.Known && entry.Full < 14*24*time.Hour:
			entry.Status = "warn"
		}
		forecasts = append(forecasts, entry)
		one := chartSeries{Name: name, Points: points}
		if entry.Status == "warn" || entry.Status == "bad" {
			one.Status = entry.Status
			series = append(series, one)
			if slope, last, ok := linearForecast(raw); ok && slope > 0 {
				end := points[len(points)-1][0]
				horizon := min(entry.Full.Seconds(), 72*3600)
				series = append(series, chartSeries{Name: name + " forecast", Status: entry.Status, Dashed: true,
					Points: [][2]float64{{end, round(last)}, {end + horizon*1000, round(min(last+slope*horizon, 1))}}})
			}
		}
	}
	slices.SortFunc(forecasts, func(left, right forecast) int {
		if left.Known != right.Known {
			if left.Known {
				return -1
			}
			return 1
		}
		return cmp.Or(cmp.Compare(left.Full, right.Full), cmp.Compare(left.Name, right.Name))
	})
	spec := chartSpec{Kind: "line", Unit: "percent", Series: series, Min: float(0), Max: float(1),
		Start:      current.Now.Add(-window).UnixMilli(),
		Thresholds: []chartThreshold{{Value: 1, Label: "full", Status: "bad"}}}
	unmeasured := 0
	for _, entry := range forecasts {
		if !entry.Trend {
			unmeasured++
		}
	}
	switch {
	case len(series) > 0:
	case len(forecasts) == 0:
		spec.Empty = "No storage history yet, so no headroom can be projected."
	case unmeasured == len(forecasts):
		spec.Empty = "Not enough storage history yet to project headroom (a trend needs at least three samples)."
	case unmeasured > 0:
		spec.Empty = "The measured filesystems have more than 14 days of headroom; " + itoa(unmeasured) +
			" have too little history to project."
	default:
		spec.Empty = "Every filesystem has more than 14 days of headroom at its current growth."
	}
	return forecasts, spec
}

func forecastText(entry forecast) string {
	switch {
	case !entry.Trend:
		return "not enough history"
	case !entry.Known:
		return "not growing"
	case entry.Full == 0:
		return "full"
	default:
		return formatDuration(entry.Full)
	}
}

func linearForecast(points [][2]float64) (slope, last float64, ok bool) {
	if len(points) < 3 {
		return 0, 0, false
	}
	var sumT, sumV, sumTT, sumTV float64
	origin := points[0][0]
	for _, point := range points {
		t := (point[0] - origin) / 1000
		sumT += t
		sumV += point[1]
		sumTT += t * t
		sumTV += t * point[1]
	}
	count := float64(len(points))
	denominator := count*sumTT - sumT*sumT
	if denominator == 0 {
		return 0, 0, false
	}
	slope = (count*sumTV - sumT*sumV) / denominator
	intercept := (sumV - slope*sumT) / count
	lastT := (points[len(points)-1][0] - origin) / 1000
	return slope, intercept + slope*lastT, true
}

// timeToFull projects when a used ratio reaches 1 from its trend.
func timeToFull(points [][2]float64) (time.Duration, bool) {
	slope, last, ok := linearForecast(points)
	if !ok || slope <= 0 || last >= 1 {
		return 0, ok && last >= 1
	}
	seconds := (1 - last) / slope
	if seconds > 365*24*3600 {
		return 0, false
	}
	return time.Duration(seconds * float64(time.Second)), true

func (spec chartSpec) JSON() string {
	data, err := json.Marshal(spec)
	if err != nil {
		return `{"kind":"line","empty":"chart unavailable"}`
	}
	return string(data)
}

