type fakeRollouts []insights.Rollout

func (rollouts fakeRollouts) Rollouts(context.Context) ([]insights.Rollout, error) {
	return rollouts, nil
}

func (rollouts fakeRollouts) Rollout(_ context.Context, id string) (insights.Rollout, error) {
	for _, record := range rollouts {
		if record.ID == id {
			return record, nil
		}
	}
	return insights.Rollout{}, ErrRolloutNotFound
}

type failingRollouts struct{}

func (failingRollouts) Rollouts(context.Context) ([]insights.Rollout, error) {
	return nil, errors.New("rollout provider: secret upstream detail")
}

func (failingRollouts) Rollout(context.Context, string) (insights.Rollout, error) {
	return insights.Rollout{}, errors.New("rollout provider: secret upstream detail")
}

type countedRollouts struct {
	rows           []insights.Rollout
	exact          map[string]insights.Rollout
	err            error
	lists, details int
}

type deadlineRollouts struct{ calls int }

func (source *deadlineRollouts) timeout(ctx context.Context) error {
	source.calls++
	readCtx, cancel := context.WithTimeout(ctx, decisionCacheTTL)
	defer cancel()
	<-readCtx.Done()
	return readCtx.Err()
}

func (source *deadlineRollouts) Rollouts(ctx context.Context) ([]insights.Rollout, error) {
	return nil, source.timeout(ctx)
}

func (source *deadlineRollouts) Rollout(ctx context.Context, _ string) (insights.Rollout, error) {
	return insights.Rollout{}, source.timeout(ctx)
}

func (source *countedRollouts) Rollouts(context.Context) ([]insights.Rollout, error) {
	source.lists++
	return slices.Clone(source.rows), source.err
}

func (source *countedRollouts) Rollout(_ context.Context, id string) (insights.Rollout, error) {
	source.details++
	if source.err != nil {
		return insights.Rollout{}, source.err
	}
	if record, ok := source.exact[id]; ok {
		return record, nil
	}
	return insights.Rollout{}, ErrRolloutNotFound
}

func newKeyedCache[V any](ttl time.Duration, limit int) *keyedCache[V] {
	return &keyedCache[V]{ttl: ttl, limit: limit, entries: map[string]cacheEntry[V]{}}
}

// get returns the cached value for key or loads it. Loads for different keys
// run concurrently; two callers of the same cold key may both load, which is
// harmless for read-only providers.
func (cache *keyedCache[V]) get(ctx context.Context, key string, load func(context.Context) (V, error)) (V, error) {
	now := time.Now()
	cache.mu.Lock()
	entry, ok := cache.entries[key]
	cache.mu.Unlock()
	if ok && now.Sub(entry.at) < cache.ttl {
		return entry.value, entry.err
	}
	value, err := load(ctx)
	if ctx.Err() != nil {
		return value, err
	}
	cache.mu.Lock()
	defer cache.mu.Unlock()
	if len(cache.entries) >= cache.limit {
		for name, old := range cache.entries {
			if now.Sub(old.at) >= cache.ttl || len(cache.entries) >= cache.limit {
				delete(cache.entries, name)
			}
		}
	}
	cache.entries[key] = cacheEntry[V]{at: time.Now(), value: value, err: err}
	return value, err
}

func rolloutStep(phase string) string {
	switch {
	case phase == "canary":
		return "canary"
	case phase == "canary-soak" || phase == "soak":
		return "soak"
	case phase == "batch" || phase == "batch-soak" || strings.HasPrefix(phase, "batch-"):
		return "batches"
	case phase == "complete":
		return "complete"
	default:
		return ""
	}
}

func rolledBack(phase string) bool { return phase == "rolled-back" || phase == "rolled_back" }

// stopped reports a rollout that waits for an operator or ended without
// completing: frozen, aborted, held or rolling back.
func stopped(phase string) bool {
	return phase == "frozen" || phase == "aborted" || phase == "held" || phase == "rolling-back"
}

func phaseStatus(rollout insights.Rollout, phase string, now time.Time) string {
	current := slices.Index(rolloutPhases, rolloutStep(rollout.Phase))
	index := slices.Index(rolloutPhases, phase)
	switch {
	case rolledBack(rollout.Phase):
		return "serious"
	case rollout.Phase == "complete":
		return "ok"
	case stopped(rollout.Phase) && index == 0:
		return "warn"
	case current < 0:
		return "idle"
	case index < current:
		return "ok"
	case index == current:
		if !rollout.PhaseDeadline.IsZero() && now.After(rollout.PhaseDeadline) {
			return "warn"
		}
		return "run"
	default:
		return "idle"
	}
}

func rolloutStatus(rollout insights.Rollout, now time.Time) string {
	switch {
	case rolledBack(rollout.Phase) || rollout.Phase == "rolling-back":
		return "serious"
	case rollout.Phase == "aborted":
		return "bad"
	case rollout.Phase == "complete":
		return "ok"
	case stopped(rollout.Phase):
		return "warn"
	case !rollout.PhaseDeadline.IsZero() && now.After(rollout.PhaseDeadline):
		return "warn"
	default:
		return "run"
	}
}

