// ago renders a relative time with the absolute time on hover. Without
// JavaScript the absolute time shows.
templ ago(value time.Time) {
	if value.IsZero() {
		<span class="muted">-</span>
	} else {
		<ts-time datetime={ rfc3339(value) } title={ formatTime(value) }>{ formatTime(value) }</ts-time>
	}
}

templ chart(class string, spec chartSpec) {
	if spec.Warning != "" {
		<p class="note warn" role="status">{ spec.Warning }</p>
	}
	<ts-chart class={ class } data-spec={ spec.JSON() } role="img" aria-label={ chartLabel(spec) }></ts-chart>

// ResourceFreshFor matches the host report's five-minute freshness window.
const ResourceFreshFor = 5 * time.Minute

// Reading keeps an observed zero distinct from an absent measurement.
type Reading struct {
	Value      float64   `json:"value"`
	ObservedAt time.Time `json:"observed_at"`
}

func (reading *Reading) Fresh(now time.Time) bool {
	return reading != nil && !reading.ObservedAt.IsZero() && !reading.ObservedAt.After(now) && now.Sub(reading.ObservedAt) <= ResourceFreshFor
}

